update public.seasons set name = 'Season 7: Bloom Vale' where id = 7;
update public.seasons set name = 'Season 8: Storm Coast' where id = 8;
update public.seasons set name = 'Season 9: Dune Sea' where id = 9;
update public.seasons set name = 'Season 10: Crystal Caves' where id = 10;
