---------------------------------------------------------------------------
-- Settings
---------------------------------------------------------------------------
alter table public.game_config
  add column if not exists bounty_l            int not null default 150,
  add column if not exists auction_refund_pct  int not null default 90 check (auction_refund_pct between 0 and 100),
  add column if not exists tokens_per_coin     numeric not null default 1 check (tokens_per_coin > 0),
  add column if not exists auction_extend_min  int not null default 5,
  add column if not exists mint_supply_c       int not null default 50,
  add column if not exists mint_supply_u       int not null default 20,
  add column if not exists mint_supply_r       int not null default 5,
  add column if not exists mint_supply_l       int not null default 1,
  add column if not exists min_bid_c           int not null default 50,
  add column if not exists min_bid_u           int not null default 150,
  add column if not exists min_bid_r           int not null default 500,
  add column if not exists min_bid_l           int not null default 2000;

---------------------------------------------------------------------------
-- Auctions
---------------------------------------------------------------------------
create table public.creature_auctions (
  id          serial primary key,
  species_id  smallint not null unique references public.species(id),
  season_id   int not null references public.seasons(id),
  supply      int not null check (supply > 0),
  min_bid     int not null check (min_bid > 0),
  opens_at    timestamptz not null default now(),
  closes_at   timestamptz not null,
  status      text not null default 'open' check (status in ('open','settled')),
  settled_at  timestamptz,
  created_at  timestamptz not null default now()
);

create table public.auction_bids (
  auction_id   int not null references public.creature_auctions(id) on delete cascade,
  user_id      uuid not null references public.profiles(id) on delete cascade,
  amount       bigint not null check (amount > 0),
  updated_at   timestamptz not null default now(),
  status       text not null default 'active' check (status in ('active','won','lost')),
  refund       bigint not null default 0,
  token_price  numeric,
  paid         boolean not null default false,
  paid_tx      text,
  asset_id     text,
  primary key (auction_id, user_id)
);
create index auction_bids_rank on public.auction_bids (auction_id, amount desc, updated_at);
create index auction_bids_user on public.auction_bids (user_id);

-- Pools the treasury holds in coins (10% of losing bids funds buybacks and the gacha).
create table public.treasury_pools (
  name    text primary key,
  balance bigint not null default 0
);

alter table public.creature_auctions enable row level security;
alter table public.auction_bids      enable row level security;
alter table public.treasury_pools    enable row level security;
create policy "read auctions" on public.creature_auctions for select to authenticated using (true);
create policy "own bids"      on public.auction_bids      for select to authenticated using (user_id = (select auth.uid()));
create policy "admin pools"   on public.treasury_pools    for select to authenticated using (is_admin());
grant select on public.creature_auctions, public.auction_bids, public.treasury_pools to authenticated;
revoke all on public.creature_auctions, public.auction_bids, public.treasury_pools from anon;
